={{ (() => {
  const texto = ($json.text || $json.transcription || '').toString().trim();
  if (!texto || texto === 'null' || texto === 'undefined' || texto.trim().length < 3) return '__AUDIO_VACIO__';

  let t = texto
    // OI — SOLO cuando se menciona explícitamente como línea/producto
    // Casos legítimos: "la oi", "línea oi", "sobre oi", "aceite oi", "productos oi"
    .replace(/\b(l[ií]nea|sobre|aceite|productos?|tratamiento|la|del?)\s+(oi|o\.i\.?)\b/gi, '$1 OI')
    // "oi" al inicio de frase como nombre de línea (ej: "oi es muy buena")
    .replace(/^(oi|o\.i\.?)\s+/i, 'OI ')
    // "oi" después de coma o punto (ej: "quiero saber de oi, ")  
    .replace(/[,\.]\s*(oi|o\.i\.?)\b/gi, ', OI')
    // NUNCA reemplazar "hoy", "voy", "soy", "estoy", "doy", "boy" → los dejamos como están

    // NOUNOU
    .replace(/\bnu\s*nu\b/gi, 'NOUNOU')
    .replace(/\bnu\s*nou\b/gi, 'NOUNOU')
    .replace(/\bnunou\b/gi, 'NOUNOU')
    .replace(/\bno\s*nu\b/gi, 'NOUNOU')
    // NOURISHING
    .replace(/\bno\s*breachin\b/gi, 'NOURISHING')
    .replace(/\bno\s*breach\b/gi, 'NOURISHING')
    .replace(/\bnobrichin\b/gi, 'NOURISHING')
    .replace(/\bno\s*brichin\b/gi, 'NOURISHING')
    .replace(/\bnourish\b/gi, 'NOURISHING')
    // MOMO
    .replace(/\bmo\s*mo\b/gi, 'MOMO')
    .replace(/\bmumu\b/gi, 'MOMO')
    .replace(/\bmumo\b/gi, 'MOMO')
    // MELU
    .replace(/\bmellu\b/gi, 'MELU')
    .replace(/\bmelu\b/gi, 'MELU')
    // MINU
    .replace(/\bminnu\b/gi, 'MINU')
    .replace(/\bminiu\b/gi, 'MINU')
    // DEDE
    .replace(/\bde\s*de\b/gi, 'DEDE')
    // PURIFYING
    .replace(/\bpurifain\b/gi, 'PURIFYING')
    .replace(/\bpurifyin\b/gi, 'PURIFYING')
    .replace(/\bpurifyng\b/gi, 'PURIFYING')
    .replace(/\bpurificando\b/gi, 'PURIFYING')
    // ENERGIZING
    .replace(/\benerjizing\b/gi, 'ENERGIZING')
    .replace(/\benergizin\b/gi, 'ENERGIZING')
    .replace(/\benerjizin\b/gi, 'ENERGIZING')
    .replace(/\benergy\s*design\b/gi, 'ENERGIZING')
    .replace(/\benergy\s*sign\b/gi, 'ENERGIZING')
    .replace(/\benergizin\b/gi, 'ENERGIZING')
    .replace(/\benergizing\b/gi, 'ENERGIZING')
    .replace(/\bener\s*sizing\b/gi, 'ENERGIZING')
    .replace(/\bener\s*gizing\b/gi, 'ENERGIZING')
    // CALMING
    .replace(/\bkalming\b/gi, 'CALMING')
    .replace(/\bcalmin\b/gi, 'CALMING')
    // REPLUMPING
    .replace(/\breplunpin\b/gi, 'REPLUMPING')
    .replace(/\breplumpin\b/gi, 'REPLUMPING')
    .replace(/\breplopin\b/gi, 'REPLUMPING')
    .replace(/\breplonping\b/gi, 'REPLUMPING')
    .replace(/\bremplamping\b/gi, 'REPLUMPING')
    .replace(/\bremplapin\b/gi, 'REPLUMPING')
    .replace(/\bremplampin\b/gi, 'REPLUMPING')
    // REBALANCING
    .replace(/\brebalancin\b/gi, 'REBALANCING')
    .replace(/\brebalansing\b/gi, 'REBALANCING')
    // DETOXIFYING
    .replace(/\bdetoxifyin\b/gi, 'DETOXIFYING')
    .replace(/\bdetoksifyin\b/gi, 'DETOXIFYING')
    .replace(/\bdetox\b/gi, 'DETOXIFYING')
    // LOVE CURL
    .replace(/\blove\s*cur\b/gi, 'LOVE CURL')
    .replace(/\blove\s*curl\b/gi, 'LOVE CURL')
    // LOVE SMOOTHING
    .replace(/\blove\s*smoot\b/gi, 'LOVE SMOOTHING')
    .replace(/\blove\s*smoothin\b/gi, 'LOVE SMOOTHING')
    .replace(/\blove\s*smoothing\b/gi, 'LOVE SMOOTH')
    .replace(/\bdamor\s*inside\b/gi, 'MORE INSIDE')
    .replace(/\bdamore\s*inside\b/gi, 'MORE INSIDE')
    .replace(/\bmore\s*inside\b/gi, 'MORE INSIDE')
    .replace(/\bmore\s*insaid\b/gi, 'MORE INSIDE')
// DECOLORACIÓN (corrección de audio)
.replace(/\bde\s+coloraci[oó]n\b/gi, 'decoloración')
.replace(/\bde\s+color\b/gi, 'decoloración')
// NOUNOU adicionales
.replace(/\bdebiub\b/gi, 'DAVINES')
.replace(/\bnew\s*rich\w*/gi, 'NOURISHING')
// THE CENTURY OF LIGHT adicionales
.replace(/\bcentury\s*of\s*the\s*light\b/gi, 'THE CENTURY OF LIGHT')
.replace(/\bthe\s*century\b/gi, 'THE CENTURY OF LIGHT')
    // THE CENTURY OF LIGHT
    .replace(/\bcentury\s*of\s*lite\b/gi, 'THE CENTURY OF LIGHT')
    .replace(/\bcentury\s*light\b/gi, 'THE CENTURY OF LIGHT')
    .replace(/\bcentro\s*de\s*la\s*luz\b/gi, 'THE CENTURY OF LIGHT')
    .replace(/\bcentury\b/gi, 'THE CENTURY OF LIGHT')
    // VIEW
    .replace(/\bviewport\b/gi, 'VIEW')
    .replace(/\bview\s*port\b/gi, 'VIEW')
    // MORE INSIDE
    .replace(/\bmore\s*insaid\b/gi, 'MORE INSIDE')
    .replace(/\bmore\s*insid\b/gi, 'MORE INSIDE');

  return t;
})() }}
